mapper.select:
SELECT 
FROM requirement r
JOIN project p ON p.id = r.project_id
WHERE r.id = #{id}
  AND r.deleted = 0
  AND p.deleted = 0
  AND (
    p.owner_id = #{ownerId}
    OR EXISTS (
      SELECT 1 FROM project_member pm
      WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
    )
  )

SELECT 
FROM requirement r
JOIN project p ON p.id = r.project_id
WHERE r.project_id = #{projectId}
  AND r.deleted = 0
  AND p.deleted = 0
  AND (
    p.owner_id = #{ownerId}
    OR EXISTS (
      SELECT 1 FROM project_member pm
      WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
    )
  )
ORDER BY r.created_at DESC, r.id DESC

SELECT 
FROM requirement r
JOIN project p ON p.id = r.project_id
WHERE r.deleted = 0
  AND p.deleted = 0
  AND (
    p.owner_id = #{ownerId}
    OR EXISTS (
      SELECT 1 FROM project_member pm
      WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
    )
